import{_ as t,o as d,c as e,Q as a}from"./chunks/framework.48927342.js";const g=JSON.parse('{"title":"Cleaner Job Application","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/practice/emails/13-cleaner-job-application.md","filePath":"en/more/maltese/practice/emails/13-cleaner-job-application.md"}'),r={name:"en/more/maltese/practice/emails/13-cleaner-job-application.md"},n=a('<h1 id="cleaner-job-application" tabindex="-1">Cleaner Job Application <a class="header-anchor" href="#cleaner-job-application" aria-label="Permalink to &quot;Cleaner Job Application&quot;">​</a></h1><p><strong>Scenario:</strong> The applicant writes to the cleaning/property company to apply for the position of cleaner.</p><h2 id="email-header" tabindex="-1">Email Header <a class="header-anchor" href="#email-header" aria-label="Permalink to &quot;Email Header&quot;">​</a></h2><p><strong>Lil (To):</strong> <a href="mailto:info@tindif.com" target="_blank" rel="noreferrer">info@tindif.com</a><strong>Mingħand (From):</strong> [isem]@email.com <strong>Data (Date):</strong> 15 ta&#39; Ottubru 2026 <strong>Suġġett (Subject):</strong> Applikazzjoni ta&#39; xogħol ta&#39; haddiem tat-tindif</p><h2 id="full-email" tabindex="-1">Full Email <a class="header-anchor" href="#full-email" aria-label="Permalink to &quot;Full Email&quot;">​</a></h2><blockquote><p><strong>Lil:</strong> <a href="mailto:info@tindif.com" target="_blank" rel="noreferrer">info@tindif.com</a><strong>Mingħand:</strong> [isem]@email.com <strong>Data:</strong> 15 ta&#39; Ottubru 2026 <strong>Suġġett:</strong> Applikazzjoni ta&#39; xogħol ta&#39; haddiem tat-tindif</p><p>Għażiż Sinjur / Sinjura,</p><p>Qed nikteb biex napplika għall-impjieg ta&#39; haddiem tat-tindif.</p><p>Għandi esperjenza ta&#39; sentejn fix-xogħol tat-tindif.</p><p>Naf naddaf djar, uffiċini u bini ieħor.</p><p>Jien bniedem li jaħdem iebes, onest u puntwali.</p><p>Nista&#39; naħdem filgħodu u filgħaxija, ukoll fi tmiem il-ġimgħa.</p><p>Jimpurtani li nżomm kollox nadif u ordnat.</p><p>Nispera li nisma&#39; mingħandkom dalwaqt.</p><p>Grazzi talli qiesu l-applikazzjoni tiegħi.</p><p>Tislijiet, [Ismek]</p></blockquote><h2 id="sentence-by-sentence-translation-and-word-notes" tabindex="-1">Sentence-by-Sentence Translation and Word Notes <a class="header-anchor" href="#sentence-by-sentence-translation-and-word-notes" aria-label="Permalink to &quot;Sentence-by-Sentence Translation and Word Notes&quot;">​</a></h2><p><strong>Malti:</strong> Lil: <a href="mailto:info@tindif.com" target="_blank" rel="noreferrer">info@tindif.com</a></p><p><strong>Translation:</strong> To: <a href="mailto:info@tindif.com" target="_blank" rel="noreferrer">info@tindif.com</a></p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Lil</td><td>to; recipient</td><td>Maltese label for the email &quot;To&quot; field</td></tr><tr><td><a href="mailto:info@tindif.com" target="_blank" rel="noreferrer">info@tindif.com</a></td><td>email address</td><td>The cleaning company&#39;s recruitment email (example)</td></tr></tbody></table><p><strong>Malti:</strong> Mingħand: [isem]@email.com</p><p><strong>Translation:</strong> From: [your name]@email.com</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Mingħand</td><td>from; sender</td><td>Maltese label for the email &quot;From&quot; field; literally &quot;from ...&quot;</td></tr><tr><td>[isem]@email.com</td><td>email address</td><td>Placeholder for your email; replace with your real one</td></tr></tbody></table><p><strong>Malti:</strong> Data: 15 ta&#39; Ottubru 2026</p><p><strong>Translation:</strong> Date: 15 October 2026</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Data</td><td>date</td><td>Email &quot;Date&quot; field; Maltese date format is &quot;day ta&#39; month year&quot;</td></tr><tr><td>15</td><td>fifteen</td><td>Day in the date</td></tr><tr><td>ta&#39;</td><td>of</td><td>Links the day and the month</td></tr><tr><td>Ottubru</td><td>October</td><td>Month name</td></tr></tbody></table><p><strong>Malti:</strong> Suġġett: Applikazzjoni ta&#39; xogħol ta&#39; haddiem tat-tindif</p><p><strong>Translation:</strong> Subject: Application for the Position of Cleaner</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Suġġett</td><td>subject</td><td>Email &quot;Subject&quot; field</td></tr><tr><td>Applikazzjoni</td><td>application</td><td>Feminine loanword from application</td></tr><tr><td>ta&#39;</td><td>of</td><td>Possession linker</td></tr><tr><td>xogħol</td><td>work; job</td><td>Masculine noun</td></tr><tr><td>ta&#39;</td><td>of</td><td>Possession linker</td></tr><tr><td>haddiem</td><td>worker</td><td>Masculine noun</td></tr><tr><td>tat-tindif</td><td>of cleaning</td><td>Contracted <code>ta&#39;</code> + <code>it-tindif</code></td></tr></tbody></table><p><strong>Malti:</strong> Għażiż Sinjur / Sinjura,</p><p><strong>Translation:</strong> Dear Sir / Madam,</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Għażiż</td><td>dear</td><td>Masculine singular form</td></tr><tr><td>Sinjur</td><td>sir; Mr.</td><td>Masculine noun</td></tr><tr><td>/</td><td>or</td><td>Indicates a choice between two</td></tr><tr><td>Sinjura</td><td>madam; Mrs.</td><td>Feminine noun</td></tr></tbody></table><h3 id="_1" tabindex="-1">1. <a class="header-anchor" href="#_1" aria-label="Permalink to &quot;1.&quot;">​</a></h3><p><strong>Malti:</strong> Qed nikteb biex napplika għall-impjieg ta&#39; haddiem tat-tindif.</p><p><strong>Translation:</strong> I am writing to apply for the position of cleaner.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Qed</td><td>am (progressive marker)</td><td>Used with a verb to indicate an ongoing action</td></tr><tr><td>nikteb</td><td>I write</td><td>First-person singular present</td></tr><tr><td>biex</td><td>in order to</td><td>Introduces a purpose clause</td></tr><tr><td>napplika</td><td>I apply</td><td>First-person singular form, loanword from apply</td></tr><tr><td>għall-impjieg</td><td>for the job</td><td>Contracted <code>għal</code> + <code>l-impjieg</code></td></tr><tr><td>ta&#39;</td><td>of</td><td>Possession linker</td></tr><tr><td>haddiem</td><td>worker</td><td>Masculine noun</td></tr><tr><td>tat-tindif</td><td>of cleaning</td><td>Contracted <code>ta&#39;</code> + <code>it-tindif</code></td></tr></tbody></table><h3 id="_2" tabindex="-1">2. <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;2.&quot;">​</a></h3><p><strong>Malti:</strong> Għandi esperjenza ta&#39; sentejn fix-xogħol tat-tindif.</p><p><strong>Translation:</strong> I have two years of experience in cleaning work.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Għandi</td><td>I have</td><td>First-person singular form of <code>għand</code></td></tr><tr><td>esperjenza</td><td>experience</td><td>Feminine noun</td></tr><tr><td>ta&#39;</td><td>of</td><td>Possession linker</td></tr><tr><td>sentejn</td><td>two years</td><td>Fixed form meaning &quot;two years&quot;</td></tr><tr><td>fix-xogħol</td><td>in the work</td><td>Contracted <code>f&#39;</code> + <code>ix-xogħol</code></td></tr><tr><td>tat-tindif</td><td>of cleaning</td><td>Contracted <code>ta&#39;</code> + <code>it-tindif</code></td></tr></tbody></table><h3 id="_3" tabindex="-1">3. <a class="header-anchor" href="#_3" aria-label="Permalink to &quot;3.&quot;">​</a></h3><p><strong>Malti:</strong> Naf naddaf djar, uffiċini u bini ieħor.</p><p><strong>Translation:</strong> I can clean houses, offices, and other buildings.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Naf</td><td>I know; I can</td><td>First-person singular form</td></tr><tr><td>naddaf</td><td>I clean</td><td>First-person singular present</td></tr><tr><td>djar</td><td>houses</td><td>Plural of <code>dar</code></td></tr><tr><td>uffiċini</td><td>offices</td><td>Plural of <code>uffiċċju</code></td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>bini</td><td>buildings</td><td>Collective noun</td></tr><tr><td>ieħor</td><td>other</td><td>Masculine singular form</td></tr></tbody></table><h3 id="_4" tabindex="-1">4. <a class="header-anchor" href="#_4" aria-label="Permalink to &quot;4.&quot;">​</a></h3><p><strong>Malti:</strong> Jien bniedem li jaħdem iebes, onest u puntwali.</p><p><strong>Translation:</strong> I am a hard-working, honest, and punctual person.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Jien</td><td>I</td><td>First-person singular pronoun</td></tr><tr><td>bniedem</td><td>person; human being</td><td>Masculine noun</td></tr><tr><td>li</td><td>who; that</td><td>Relative pronoun</td></tr><tr><td>jaħdem</td><td>he works</td><td>Third-person masculine singular</td></tr><tr><td>iebes</td><td>hard; industrious</td><td>Used as an adverb &quot;hard&quot; here</td></tr><tr><td>onest</td><td>honest</td><td>Adjective loanword from honest</td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>puntwali</td><td>punctual</td><td>Adjective loanword from punctual</td></tr></tbody></table><h3 id="_5" tabindex="-1">5. <a class="header-anchor" href="#_5" aria-label="Permalink to &quot;5.&quot;">​</a></h3><p><strong>Malti:</strong> Nista&#39; naħdem filgħodu u filgħaxija, ukoll fi tmiem il-ġimgħa.</p><p><strong>Translation:</strong> I can work in the morning and in the evening, also at weekends.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Nista&#39;</td><td>I can</td><td>First-person singular form</td></tr><tr><td>naħdem</td><td>I work</td><td>First-person singular present</td></tr><tr><td>filgħodu</td><td>in the morning</td><td>Time expression</td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>filgħaxija</td><td>in the evening</td><td>Time expression</td></tr><tr><td>ukoll</td><td>also</td><td>Adverb</td></tr><tr><td>fi</td><td>in</td><td>Variant of the preposition <code>f&#39;</code></td></tr><tr><td>tmiem</td><td>end; close</td><td><code>tmiem il-ġimgħa</code> is a fixed phrase meaning &quot;weekend&quot;</td></tr><tr><td>il-ġimgħa</td><td>the week</td><td>Feminine noun with the definite article</td></tr></tbody></table><h3 id="_6" tabindex="-1">6. <a class="header-anchor" href="#_6" aria-label="Permalink to &quot;6.&quot;">​</a></h3><p><strong>Malti:</strong> Jimpurtani li nżomm kollox nadif u ordnat.</p><p><strong>Translation:</strong> I care about keeping everything clean and tidy.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Jimpurtani</td><td>I care</td><td><code>jimpurta</code> + <code>-ni</code> &quot;me&quot;; idiomatic expression</td></tr><tr><td>li</td><td>that; introduces a clause</td><td>Conjunction</td></tr><tr><td>nżomm</td><td>I keep</td><td>First-person singular form</td></tr><tr><td>kollox</td><td>everything; all</td><td>Indefinite pronoun</td></tr><tr><td>nadif</td><td>clean</td><td>Masculine singular adjective</td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>ordnat</td><td>tidy; orderly</td><td>Adjective loanword from ordinate</td></tr></tbody></table><h3 id="_7" tabindex="-1">7. <a class="header-anchor" href="#_7" aria-label="Permalink to &quot;7.&quot;">​</a></h3><p><strong>Malti:</strong> Nispera li nisma&#39; mingħandkom dalwaqt.</p><p><strong>Translation:</strong> I hope to hear from you soon.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Nispera</td><td>I hope</td><td>First-person singular form</td></tr><tr><td>li</td><td>that; introduces a clause</td><td>Conjunction</td></tr><tr><td>nisma&#39;</td><td>I hear; receive news</td><td>First-person singular form</td></tr><tr><td>mingħandkom</td><td>from you (plural)</td><td><code>mingħand</code> + <code>-kom</code> &quot;you&quot;</td></tr><tr><td>dalwaqt</td><td>soon</td><td>Adverb</td></tr></tbody></table><h3 id="_8" tabindex="-1">8. <a class="header-anchor" href="#_8" aria-label="Permalink to &quot;8.&quot;">​</a></h3><p><strong>Malti:</strong> Grazzi talli qiesu l-applikazzjoni tiegħi.</p><p><strong>Translation:</strong> Thank you for considering my application.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Grazzi</td><td>thank you</td><td>Polite phrase</td></tr><tr><td>talli</td><td>for (your) ...</td><td>Written expression introducing a reason</td></tr><tr><td>qiesu</td><td>they considered</td><td>Third-person plural past of <code>qies</code></td></tr><tr><td>l-applikazzjoni</td><td>the application</td><td>Feminine noun with the definite article</td></tr><tr><td>tiegħi</td><td>my; mine</td><td>Possessive pronoun</td></tr></tbody></table><p><strong>Malti:</strong> Tislijiet, [Ismek]</p><p><strong>Translation:</strong> Regards, [your name] (formal email closing).</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Tislijiet</td><td>regards; best wishes</td><td>Formal email/letter closing, literally &quot;greetings/regards&quot;</td></tr><tr><td>Ismek</td><td>your name</td><td><code>isem</code> &quot;name&quot; + <code>-ek</code> &quot;your&quot;; replace with your real name</td></tr></tbody></table>',57),o=[n];function i(l,s,h,p,c,m){return d(),e("div",null,o)}const f=t(r,[["render",i]]);export{g as __pageData,f as default};
